import{_ as e,o as l,c as o,ag as i}from"./chunks/framework.BYYsWsaA.js";const p=JSON.parse('{"title":"域名与跨域配置说明","description":"","frontmatter":{},"headers":[],"relativePath":"domain-and-cors-setup.md","filePath":"domain-and-cors-setup.md","lastUpdated":1773599229000}'),d={name:"domain-and-cors-setup.md"};function t(r,a,c,h,n,s){return l(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="域名与跨域配置说明" tabindex="-1">域名与跨域配置说明 <a class="header-anchor" href="#域名与跨域配置说明" aria-label="Permalink to &quot;域名与跨域配置说明&quot;">​</a></h1><h2 id="目标域名规划" tabindex="-1">目标域名规划 <a class="header-anchor" href="#目标域名规划" aria-label="Permalink to &quot;目标域名规划&quot;">​</a></h2><p>当前项目建议按下面的方式拆分域名：</p><ul><li><code>heartguard.cn</code><ul><li>用作官网展示页、项目介绍页、下载入口</li></ul></li><li><code>console.heartguard.cn</code><ul><li>用作后台管理控制台</li></ul></li><li><code>api.heartguard.cn</code><ul><li>用作 Django REST API</li></ul></li></ul><p>这种拆分有几个直接好处：</p><ul><li>前后端职责清晰</li><li>后续官网、管理台、App、小程序可以共存</li><li>部署和反向代理更容易维护</li><li>权限和安全边界更清楚</li></ul><h2 id="已配置的后端设置" tabindex="-1">已配置的后端设置 <a class="header-anchor" href="#已配置的后端设置" aria-label="Permalink to &quot;已配置的后端设置&quot;">​</a></h2><p>后端配置文件：</p><ul><li><code>backend/config/settings.py</code></li></ul><p>已默认加入以下域名：</p><h3 id="allowed-hosts" tabindex="-1">ALLOWED_HOSTS <a class="header-anchor" href="#allowed-hosts" aria-label="Permalink to &quot;ALLOWED_HOSTS&quot;">​</a></h3><p>默认包含：</p><ul><li><code>127.0.0.1</code></li><li><code>localhost</code></li><li><code>heartguard.cn</code></li><li><code>console.heartguard.cn</code></li><li><code>api.heartguard.cn</code></li></ul><h3 id="cors-allowed-origins" tabindex="-1">CORS_ALLOWED_ORIGINS <a class="header-anchor" href="#cors-allowed-origins" aria-label="Permalink to &quot;CORS_ALLOWED_ORIGINS&quot;">​</a></h3><p>默认包含：</p><ul><li><code>http://localhost:5173</code></li><li><code>http://127.0.0.1:5173</code></li><li><code>https://heartguard.cn</code></li><li><code>https://console.heartguard.cn</code></li></ul><p>说明：</p><ul><li>控制台部署到 <code>console.heartguard.cn</code> 后，可以直接跨域访问 <code>api.heartguard.cn</code></li><li>官网如果未来要展示公开数据或做演示，也保留了 <code>heartguard.cn</code> 的跨域入口</li></ul><h3 id="csrf-trusted-origins" tabindex="-1">CSRF_TRUSTED_ORIGINS <a class="header-anchor" href="#csrf-trusted-origins" aria-label="Permalink to &quot;CSRF_TRUSTED_ORIGINS&quot;">​</a></h3><p>默认包含：</p><ul><li><code>http://localhost:5173</code></li><li><code>http://127.0.0.1:5173</code></li><li><code>https://heartguard.cn</code></li><li><code>https://console.heartguard.cn</code></li><li><code>https://api.heartguard.cn</code></li></ul><p>说明：</p><ul><li>即使当前控制台主要走 Token 鉴权，这个配置仍然建议保留</li><li>后续如果接入 Django Session、后台表单或其他管理接口，会更稳</li></ul><h3 id="cors-allow-credentials" tabindex="-1">CORS_ALLOW_CREDENTIALS <a class="header-anchor" href="#cors-allow-credentials" aria-label="Permalink to &quot;CORS_ALLOW_CREDENTIALS&quot;">​</a></h3><p>默认开启：</p><ul><li><code>true</code></li></ul><h3 id="secure-proxy-ssl-header" tabindex="-1">SECURE_PROXY_SSL_HEADER <a class="header-anchor" href="#secure-proxy-ssl-header" aria-label="Permalink to &quot;SECURE_PROXY_SSL_HEADER&quot;">​</a></h3><p>已设置：</p><ul><li><code>(&#39;HTTP_X_FORWARDED_PROTO&#39;, &#39;https&#39;)</code></li></ul><p>作用：</p><ul><li>当你通过 Nginx 或云服务器反向代理接入 HTTPS 时，Django 可以正确识别外层协议</li></ul><h2 id="环境变量文件" tabindex="-1">环境变量文件 <a class="header-anchor" href="#环境变量文件" aria-label="Permalink to &quot;环境变量文件&quot;">​</a></h2><h3 id="后端" tabindex="-1">后端 <a class="header-anchor" href="#后端" aria-label="Permalink to &quot;后端&quot;">​</a></h3><p>示例文件：</p><ul><li><code>backend/.env.example</code></li></ul><p>你部署时建议复制为：</p><ul><li><code>backend/.env</code></li></ul><h3 id="前端控制台" tabindex="-1">前端控制台 <a class="header-anchor" href="#前端控制台" aria-label="Permalink to &quot;前端控制台&quot;">​</a></h3><p>开发环境示例：</p><ul><li><code>console/.env.example</code></li></ul><p>生产环境示例：</p><ul><li><code>console/.env.production.example</code></li></ul><p>其中生产环境 API 地址建议为：</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">VITE_API_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://api.heartguard.cn/api/v1</span></span></code></pre></div><h2 id="推荐部署关系" tabindex="-1">推荐部署关系 <a class="header-anchor" href="#推荐部署关系" aria-label="Permalink to &quot;推荐部署关系&quot;">​</a></h2><h3 id="官网" tabindex="-1">官网 <a class="header-anchor" href="#官网" aria-label="Permalink to &quot;官网&quot;">​</a></h3><ul><li>域名：<code>heartguard.cn</code></li><li>可以后续单独做 Vue 静态站、营销页、项目展示页</li></ul><h3 id="控制台" tabindex="-1">控制台 <a class="header-anchor" href="#控制台" aria-label="Permalink to &quot;控制台&quot;">​</a></h3><ul><li>域名：<code>console.heartguard.cn</code></li><li>运行当前 <code>console</code> 前端产物</li></ul><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li>域名：<code>api.heartguard.cn</code></li><li>反向代理到 Django <code>gunicorn / uvicorn / runserver</code> 所在端口</li></ul><h2 id="典型反向代理思路" tabindex="-1">典型反向代理思路 <a class="header-anchor" href="#典型反向代理思路" aria-label="Permalink to &quot;典型反向代理思路&quot;">​</a></h2><h3 id="控制台域名" tabindex="-1">控制台域名 <a class="header-anchor" href="#控制台域名" aria-label="Permalink to &quot;控制台域名&quot;">​</a></h3><ul><li><code>console.heartguard.cn</code> 指向前端打包后的静态文件目录</li></ul><h3 id="api-域名" tabindex="-1">API 域名 <a class="header-anchor" href="#api-域名" aria-label="Permalink to &quot;API 域名&quot;">​</a></h3><ul><li><code>api.heartguard.cn</code> 指向 Django 服务</li></ul><p>例如：</p><ul><li><code>https://console.heartguard.cn</code> -&gt; Vue 构建产物</li><li><code>https://api.heartguard.cn/api/v1/...</code> -&gt; Django</li></ul><h2 id="开发与生产的区别" tabindex="-1">开发与生产的区别 <a class="header-anchor" href="#开发与生产的区别" aria-label="Permalink to &quot;开发与生产的区别&quot;">​</a></h2><h3 id="开发环境" tabindex="-1">开发环境 <a class="header-anchor" href="#开发环境" aria-label="Permalink to &quot;开发环境&quot;">​</a></h3><ul><li>控制台：<code>http://localhost:5173</code></li><li>API：<code>http://127.0.0.1:8000</code></li></ul><h3 id="生产环境" tabindex="-1">生产环境 <a class="header-anchor" href="#生产环境" aria-label="Permalink to &quot;生产环境&quot;">​</a></h3><ul><li>控制台：<code>https://console.heartguard.cn</code></li><li>API：<code>https://api.heartguard.cn</code></li><li>官网：<code>https://heartguard.cn</code></li></ul><h2 id="当前建议" tabindex="-1">当前建议 <a class="header-anchor" href="#当前建议" aria-label="Permalink to &quot;当前建议&quot;">​</a></h2><p>现阶段你可以先：</p><ol><li>保留 <code>heartguard.cn</code> 作为官网展示位</li><li>把控制台规划为 <code>console.heartguard.cn</code></li><li>把后端 API 规划为 <code>api.heartguard.cn</code></li><li>前端生产环境统一指向 <code>https://api.heartguard.cn/api/v1</code></li></ol><p>这样后续做官网时，不需要再重构当前控制台和后端的部署边界。</p>',67)])])}const g=e(d,[["render",t]]);export{p as __pageData,g as default};
